catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   g_form.setDisplay('please_select_the_required_quantity', true);
   g_form.setMandatory('please_select_the_required_quantity', true);
   g_form.setDisplay('desired_date_of_delivery', true);
   g_form.setMandatory('desired_date_of_delivery', true);
   g_form.setDisplay('last_accepted_date_of_delivery', true);
   g_form.setMandatory('last_accepted_date_of_delivery', true);
   g_form.setDisplay('location_of_delivery', true);
   g_form.setMandatory('location_of_delivery', true);
   g_form.setDisplay('did_you_enjoy_your_previous_coffee_order', true);
   g_form.setMandatory('did_you_enjoy_your_previous_coffee_order', true);

}
